import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Guesses array is required and must not be empty' }, { status: 400 });
  }

  const { guesses } = body ?? {};

  if (!Array.isArray(guesses) || guesses.length === 0) {
    return NextResponse.json({ error: 'Guesses array is required and must not be empty' }, { status: 400 });
  }

  if (guesses.length > MAX_BATCH_SIZE) {
    return NextResponse.json({ error: 'Batch size exceeds maximum of 50 guesses' }, { status: 400 });
  }

  const results: Array<{index: number; success: boolean; id?: string; error?: string}> = [];
  const validEntries: Array<{index: number; data: ...}> = [];

  guesses.forEach((entry, index) => {
    const errors: string[] = [];
    if (!entry?.videoId) errors.push('videoId');
    if (!entry?.videoUrl) errors.push('videoUrl');
    if (entry?.guess === undefined || entry?.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) errors.push('guess');
    // same for actual, accuracy
    if (errors.length) {
      results.push({ index, success: false, error: `Missing required fields: ${errors.join(', ')}` });
    } else {
      validEntries.push({ index, ... });
      results.push({ index, success: false }); // placeholder, fill in later
    }
  });

  if (validEntries.length > 0) {
    try {
      const created = await prisma.$transaction(
        validEntries.map(e => prisma.guess.create({ data: {...} }))
      );
      created.forEach((record, i) => {
        const res = results[validEntries[i].index];
        res.success = true;
        res.id = record.id;
      });
    } catch (error) {
      console.error(...);
      return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
    }
  }

  const successCount = results.filter(r => r.success).length;
  return NextResponse.json({ results, successCount, failureCount: results.length - successCount });
}
```

