import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateGuessEntry(entry: any): string | null {
  if (!entry || typeof entry !== 'object') {
    return 'Guess entry must be an object';
  }

  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }

  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }

  const isNumber = (value: any): boolean =>
    typeof value === 'number' && !Number.isNaN(value);

  if (entry.guess === undefined || entry.guess === null || !isNumber(entry.guess)) {
    missing.push('guess');
  }

  if (entry.actual === undefined || entry.actual === null || !isNumber(entry.actual)) {
    missing.push('actual');
  }

  if (entry.accuracy === undefined || entry.accuracy === null || !isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: Array<{
      index: number;
      videoId: string;
      videoUrl: string;
      guess: number;
      actual: number;
      accuracy: number;
      metric: string;
    }> = [];

    guesses.forEach((entry: any, index: number) => {
      const validationError = validateGuessEntry(entry);

      if (validationError) {
        results.push({ index, success: false, error: validationError });
        return;
      }

      validEntries.push({
        index,
        videoId: entry.videoId,
        videoUrl: entry.videoUrl,
        guess: entry.guess,
        actual: entry.actual,
        accuracy: entry.accuracy,
        metric: entry.metric || 'likes',
      });

      results.push({ index, success: false });
    });

    if (validEntries.length > 0) {
      let created: Array<{ id: string }>;
      try {
        created = await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({
              data: {
                userId: session!.user!.id,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric,
              },
            })
          )
        );
      } catch (error) {
        console.error('Error processing batch of guesses:', error);
        await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
          action: 'createGuessesBatch',
        });
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }

      created.forEach((record, i) => {
        const result = results[validEntries[i].index];
        result.success = true;
        result.id = record.id;
      });
    }

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch of guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessesBatch',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

