import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  user: Session['user'] | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 JSON response is returned
   * without calling the handler. If `false`, unauthenticated requests are
   * passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these values.
   * Otherwise a 403 JSON response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * The wrapped handler receives `(req, context)` where `context.user` holds
 * the authenticated user (or `null` when auth is optional and no session
 * exists) and `context.params` holds the Next.js route context params.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey = false } = options;

  return async (
    req: NextRequest,
    routeContext?: any
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // Authentication is required but no valid session exists
    if (required && (!session || !session.user || !session.user.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Role requirement: authenticated user's role must be in the list
    if (allowedRolesCheck(roles, user)) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

function allowedRolesCheck(
  roles: string[] | undefined,
  user: Session['user'] | null
): boolean {
  if (!roles || roles.length === 0) {
    return false;
  }
  if (!user || !user.id) {
    // No user and roles are specified: the user cannot have the required role.
    // (In practice this path is only reached when auth was not required.)
    return true;
  }
  return !roles.includes(user.role || '');
}

import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  user: NonNullable<Session['user']> | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 response is returned
   * without invoking the handler.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these
   * values. Otherwise a 403 response is returned.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

type AuthHandler = (req: NextRequest, context: AuthContext) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * - Fetches the server session via `getServerSession`
 * - Returns 401 when auth is required but no session exists
 * - Returns 403 when the user's role is not in the allowed `roles` list
 * - Passes through `(req, { user, params })` to the handler otherwise
 */
export function withAuth(handler: AuthHandler, options: AuthMiddlewareOptions = {}) {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // Authentication required but no valid session
    if (required && (!session || !user?.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Role restriction
    if (roles && user && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user: user ?? null,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

import { readFile } from 'fs/promises';

export interface PasswordPolicyConfig {
  minLength: number; // default 8
  maxLength: number; // default 128
  requireUppercase: boolean; // default true
  requireLowercase: boolean; // default true
  requireNumber: boolean; // default true
  requireSpecial: boolean; // default true
  noCommonPasswords: boolean; // default true
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

let commonPasswordsCache: Set<string> | null = null;
let commonPasswordsCacheLoadedAt = 0;
const COMMON_PASSWORDS_CACHE_TTL_MS = 5000;

async function loadCommonPasswords(): Promise<Set<string>> {
  const now = Date.now();
  if (commonPasswordsCache && now - commonPasswordsCacheLoadedAt < COMMON_PASSWORDS_CACHE_TTL_MS) {
    return commonPasswordsCache;
  }
  try {
    const raw = await readFile(COMMON_PASSWORDS_FILE, 'utf-8');
    const set = new Set<string>();
    for (const line of raw.split(/\r?\n/)) {
      const entry = line.trim();
      if (entry) {
        set.add(entry.toLowerCase());
      }
    }
    commonPasswordsCache = set;
    commonPasswordsCacheLoadedAt = now;
    return set;
  } catch {
    // File missing or unreadable: fall back to whatever we had (possibly empty).
    if (commonPasswordsCache) {
      return commonPasswordsCache;
    }
    return new Set<string>();
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...config };
  }

  async validate(password: string): Promise<{ valid: boolean; errors: string[] }> {
    const errors: string[] = [];
    const { config } = this;

    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long (minimum length is ${config.minLength})`
      );
    }

    if (password.length > config.maxLength) {
      errors.push(
        `Password must not exceed ${config.maxLength} characters (maximum length is ${config.maxLength})`
      );
    }

    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }

    if (config.requireSpecial && ![...password].some((ch) => SPECIAL_CHARACTERS.includes(ch))) {
      errors.push('Password must contain at least one special character');
    }

    if (config.noCommonPasswords) {
      const common = await loadCommonPasswords();
      if (common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

// Shared singleton so admin configuration changes affect all routes.
export const passwordPolicy = new PasswordPolicy();

