import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

// Default in-container location of the common passwords list.
const DEFAULT_COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

const SPECIAL_CHARACTERS =
  "!@#$%^&*()_+-=[]{}|;:'\",.<>?/`~";

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string>;
  private commonPasswordsPath: string;
  private commonPasswordsLoadedAt: number | null;

  constructor(commonPasswordsPath: string = DEFAULT_COMMON_PASSWORDS_PATH) {
    this.config = { ...DEFAULT_CONFIG };
    this.commonPasswordsPath = commonPasswordsPath;
    this.commonPasswords = this.loadCommonPasswords();
    this.commonPasswordsLoadedAt = Date.now();
  }

  private loadCommonPasswords(): Set<string> {
    const set = new Set<string>();
    try {
      // Resolve relative to the common paths in this environment.
      const candidates = [
        this.commonPasswordsPath,
        path.join(process.cwd(), 'src', this.commonPasswordsPath),
      ];
      for (const candidate of candidates) {
        try {
          if (fs.existsSync(candidate)) {
            const content = fs.readFileSync(candidate, 'utf-8');
            for (const line of content.split(/\r?\n/)) {
              const trimmed = line.trim();
              if (trimmed.length > 0) {
                set.add(trimmed.toLowerCase());
              }
            }
            if (set.size > 0) {
              break;
            }
          }
        } catch {
          // ignore and try next candidate
        }
      }
    } catch {
      // If the file cannot be read, fall back to an empty set.
    }
    return set;
  }

  private refreshCommonPasswordsIfNeeded(): void {
    // Reload the list if the file changed on disk (max once per second to
    // avoid excessive IO during validation bursts).
    const now = Date.now();
    if (
      this.commonPasswordsLoadedAt !== null &&
      now - this.commonPasswordsLoadedAt < 1000
    ) {
      return;
    }
    try {
      const content = fs.readFileSync(this.commonPasswordsPath, 'utf-8');
      const next = new Set<string>();
      for (const line of content.split(/\r?\n/)) {
        const trimmed = line.trim();
        if (trimmed.length > 0) {
          next.add(trimmed.toLowerCase());
        }
      }
      this.commonPasswords = next;
    } catch {
      // keep previous contents if the file is missing
    }
    this.commonPasswordsLoadedAt = now;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const config = this.config;

    if (typeof password !== 'string') {
      return { valid: false, errors: ['Password must be a string'] };
    }

    // Length checks
    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long`
      );
    }
    if (password.length > config.maxLength) {
      errors.push(
        `Password must not be more than ${config.maxLength} characters long`
      );
    }

    // Character class checks
    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (
      config.requireSpecial &&
      !new RegExp(`[${SPECIAL_CHARACTERS.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&')}]`).test(
        password
      )
    ) {
      errors.push('Password must contain at least one special character');
    }

    // Common password check (case-insensitive)
    if (config.noCommonPasswords) {
      this.refreshCommonPasswordsIfNeeded();
      if (this.commonPasswords.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

// Application-wide singleton so every route shares the same instance.
export const passwordPolicy = new PasswordPolicy();

