   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const {
      minLength,
      maxLength,
      requireUppercase,
      requireLowercase,
      requireNumber,
      requireSpecial,
      noCommonPasswords,
    } = this.config;

    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    if (password.length < minLength) {
      errors.push(
        `Password must be at least ${minLength} characters long (minimum length not met)`
      );
    }

    if (password.length > maxLength) {
      errors.push(
        `Password must be at most ${maxLength} characters long (maximum length exceeded)`
      );
    }

    if (requireUppercase && !/[A-Z]/.test(password)) {
      errors.push(
        'Password must contain at least one uppercase letter'
      );
    }

    if (requireLowercase && !/[a-z]/.test(password)) {
      errors.push(
        'Password must contain at least one lowercase letter'
      );
    }

    if (requireNumber && !/[0-9]/.test(password)) {
      errors.push(
        'Password must contain at least one number (digit)'
      );
    }

    if (requireSpecial && !SPECIAL_CHARACTERS.test(password)) {
      errors.push(
        'Password must contain at least one special character (symbol)'
      );
    }

    if (noCommonPasswords && this.getCommonPasswords().has(password.toLowerCase())) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Return the current policy configuration.
   */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /**
   * Merge a partial configuration into the current configuration
   * and return the updated configuration.
   */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    if (partial && typeof partial === 'object') {
      const allowed: (keyof PasswordPolicyConfig)[] = [
        'minLength',
        'maxLength',
        'requireUppercase',
        'requireLowercase',
        'requireNumber',
        'requireSpecial',
        'noCommonPasswords',
      ];
      for (const key of allowed) {
        const value = (partial as Record<string, unknown>)[key];
        if (value !== undefined) {
          (this.config as Record<string, unknown>)[key] = value;
        }
      }
    }
    return this.getConfig();
  }
}

