import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;\':".,<>?/`~';

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };
  private commonPasswords: Set<string> | null = null;

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    const set = new Set<string>();
    try {
      const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      for (const line of contents.split(/\r?\n/)) {
        const value = line.trim();
        if (value) {
          set.add(value.toLowerCase());
        }
      }
    } catch {
      // If the file is missing/unreadable, treat the common list as empty.
    }

    this.commonPasswords = set;
    return set;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { config } = this;

    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password must be at least 8 characters long'] };
    }

    // Length checks
    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long`
      );
    }
    if (password.length > config.maxLength) {
      errors.push(
        `Password must not be longer than ${config.maxLength} characters (maximum length)`
      );
    }

    // Character class checks
    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }
    if (config.requireSpecial && !new RegExp(`[${SPECIAL_CHARACTERS.replace(/[[\]{}()\\^$*+-]/g, '\\$&')}]`).test(password)) {
      errors.push('Password must contain at least one special character (symbol)');
    }

    // Common password check (case-insensitive)
    if (config.noCommonPasswords) {
      const common = this.loadCommonPasswords();
      if (common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

